import { cookies, headers } from 'next/headers'

export async function MemberPanel() {
  const cookieStore = await cookies()
  const requestHeaders = await headers()
  const member = cookieStore.get('member')?.value ?? 'Guest'
  const team = cookieStore.get('team')?.value ?? 'Community'
  const region = requestHeaders.get('x-region') ?? 'global'

  return (
    <>
      <p>Welcome, {member}</p>
      <p>Team: {team}</p>
      <p>Region: {region}</p>
    </>
  )
}

export function MemberPanelSkeleton() {
  return (
    <>
      <p>Welcome, …</p>
      <p>Team: …</p>
      <p>Region: …</p>
    </>
  )
}

